"""Archive/resource regressions use generated bytes, never a real dataset."""
import io
import json
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch
import zipfile

from mmd_fraud.cloud_config import validate_config
from mmd_fraud.data.acquire import (FILES, SOURCE, MAX_EXPANDED_BYTES, acquire, extract_one,
                                   verify_acquisition)
from mmd_fraud.data.mirror import TAIL_BYTES, inspect_release
from test_acquisition import Response


def zipped(name, content=b'generated\n'):
    data = io.BytesIO()
    with zipfile.ZipFile(data, 'w', compression=zipfile.ZIP_DEFLATED) as z:
        z.writestr(name, content)
    return data.getvalue()


def response(request):
    name = request.full_url.rsplit('/', 1)[1][:-4]
    return Response(zipped(name), request.full_url)


class ReleaseSafetyTests(unittest.TestCase):
    def test_real_archive_over_old_expansion_limit_is_accepted_with_reviewed_budget(self):
        # Highly compressible generated stream: no source data and <1 MB download.
        # An actual ZIP/CRC/extraction tests the boundary without mocking its declared size.
        size = 500_000_001
        with tempfile.TemporaryDirectory() as temp:
            root = Path(temp)
            archive = root / 'fixture.zip'
            with zipfile.ZipFile(archive, 'w', compression=zipfile.ZIP_DEFLATED) as z:
                with z.open(FILES[0], 'w') as out:
                    chunk = b'0' * 1024 * 1024
                    remaining = size
                    while remaining:
                        piece = chunk[:min(remaining, len(chunk))]
                        out.write(piece)
                        remaining -= len(piece)
            with self.assertRaisesRegex(ValueError, 'declared_size=500000001.*remaining_allowance=500000000'):
                extract_one(archive, root / 'csv', FILES[0], 500_000_000)
            extract_one(archive, root / 'csv', FILES[0], MAX_EXPANDED_BYTES)
            self.assertEqual((root / 'csv').stat().st_size, size)

    def test_independent_cumulative_compressed_and_expanded_limits(self):
        for compressed, expanded, message in ((100, 1000, 'download limit'),
                                               (10000, 20, 'remaining_allowance=0')):
            with self.subTest(message=message), tempfile.TemporaryDirectory() as temp, \
                    patch('mmd_fraud.data.acquire.open_remote', side_effect=response):
                root = Path(temp)
                with self.assertRaisesRegex(ValueError, message):
                    acquire(root / 'raw', compressed, expanded)
                self.assertEqual(list(root.iterdir()), [])

    def test_oversized_declared_compressed_response_is_rejected_without_read(self):
        r = response(type('Request', (), {'full_url': f'{SOURCE}/{FILES[0]}.zip'})())
        r.headers['Content-Length'] = '10001'
        with tempfile.TemporaryDirectory() as temp, patch(
                'mmd_fraud.data.acquire.open_remote', return_value=r), patch.object(r, 'read') as read:
            with self.assertRaisesRegex(ValueError, 'declared_size=10001.*download_limit=10000'):
                acquire(Path(temp) / 'raw', 10000, 10000)
            read.assert_not_called()

    def test_truncated_crc_broken_and_interrupted_responses_clean_staging(self):
        class Interrupted(Response):
            def read(self, *args):
                raise ConnectionResetError('interrupted stream')
        good = zipped(FILES[0])
        corrupt = bytearray(good)
        # Corrupt compressed data, leaving the central directory intact.
        corrupt[len(FILES[0]) + 30] ^= 255
        cases = [Response(good[:-10], f'{SOURCE}/{FILES[0]}.zip'),
                 Response(bytes(corrupt), f'{SOURCE}/{FILES[0]}.zip'),
                 Interrupted(good, f'{SOURCE}/{FILES[0]}.zip')]
        for r in cases:
            with self.subTest(r=type(r).__name__), tempfile.TemporaryDirectory() as temp, patch(
                    'mmd_fraud.data.acquire.open_remote', return_value=r):
                with self.assertRaises(Exception):
                    acquire(Path(temp) / 'raw')
                self.assertEqual(list(Path(temp).iterdir()), [])

    def test_declared_length_truncation_and_timeout_are_not_retried(self):
        for timeout in (False, True):
            r = response(type('Request', (), {'full_url': f'{SOURCE}/{FILES[0]}.zip'})())
            r.headers['Content-Length'] = str(len(r.getvalue()) + 1)
            with tempfile.TemporaryDirectory() as temp, patch(
                    'mmd_fraud.data.acquire.open_remote', return_value=r) as fetch, patch(
                    'mmd_fraud.data.acquire.time.monotonic', side_effect=[0, 601] if timeout else [0, 0]):
                with self.assertRaisesRegex((ValueError, TimeoutError),
                                            'stream budget' if timeout else 'truncated download'):
                    acquire(Path(temp) / 'raw')
                self.assertEqual(fetch.call_count, 1)
                self.assertEqual(list(Path(temp).iterdir()), [])

    def test_cache_resume_provenance_sizes_limits_and_corruption(self):
        with tempfile.TemporaryDirectory() as temp, patch(
                'mmd_fraud.data.acquire.open_remote', side_effect=response) as fetch:
            root = Path(temp) / 'raw'
            manifest = acquire(root)
            for _ in range(2):
                self.assertEqual(verify_acquisition(root), manifest)
            self.assertEqual(fetch.call_count, 3)
            for key, value in (('license', 'invented'), ('publisher', 'other'),
                               ('expanded_bytes', 0), ('downloaded_bytes', 0)):
                bad = {**manifest, key: value}
                (root / 'acquisition.json').write_text(json.dumps(bad))
                with self.assertRaises(ValueError):
                    verify_acquisition(root)
            (root / 'acquisition.json').write_text(json.dumps(manifest))
            with self.assertRaises(ValueError):
                verify_acquisition(root, max_expanded_bytes=1)
            (root / FILES[0]).write_text('corrupt')
            with self.assertRaisesRegex(ValueError, 'hashes/size/provenance'):
                verify_acquisition(root)

    def test_config_has_bounded_independent_budgets_and_downstream_coverage(self):
        c = validate_config({})
        self.assertGreater(c['max_expanded_bytes'], 697459499)
        for invalid in ({'max_download_bytes': True}, {'max_expanded_bytes': 0},
                        {'max_expanded_bytes': 2_000_000_000}, {'acquisition_seconds': -1}):
            with self.assertRaises(ValueError):
                validate_config(invalid)
        self.assertEqual(validate_config({'max_download_bytes': 1234})['max_expanded_bytes'],
                         MAX_EXPANDED_BYTES)
        repo = Path(__file__).resolve().parents[1]
        self.assertGreaterEqual(json.loads((repo / 'configs/profiles.json').read_text())
                                ['medium']['max_input_bytes'], 697459499)

    def test_metadata_is_bounded_and_rejects_full_or_truncated_http_responses(self):
        def remote(request):
            r = response(request)
            total = len(r.getvalue())
            r.status = 206
            r.headers['Content-Range'] = f'bytes 0-{total-1}/{total}'
            return r
        with patch('mmd_fraud.data.mirror.open_remote', side_effect=remote):
            metadata = inspect_release()
        self.assertEqual(len(metadata['files']), 3)
        self.assertLessEqual(metadata['metadata_bytes_read'], 3 * TAIL_BYTES)
        for status, content_range in ((200, ''), (206, 'bytes 0-999/1000')):
            r = response(type('Request', (), {'full_url': f'{SOURCE}/{FILES[0]}.zip'})())
            r.status = status
            r.headers['Content-Range'] = content_range
            with patch('mmd_fraud.data.mirror.open_remote', return_value=r):
                with self.assertRaises(ValueError):
                    inspect_release()

    def test_workflow_reuses_verified_private_raw_cache_after_workspace_loss(self):
        from mmd_fraud.automation import run_workflow
        import shutil
        with tempfile.TemporaryDirectory() as temp, patch(
                'mmd_fraud.automation.cloud_runtime', return_value='colab'), patch(
                'mmd_fraud.data.acquire.open_remote', side_effect=response) as fetch, patch(
                'mmd_fraud.spark.pipeline.run', side_effect=ValueError('stop after verified acquisition')):
            root = Path(temp)
            repo = Path(__file__).resolve().parents[1]
            for attempt in range(2):
                with self.assertRaisesRegex(ValueError, 'stop after verified acquisition'):
                    run_workflow(repo, root / 'work', {'source': 'pyg'}, root / 'store', run_tests=False)
                self.assertEqual(fetch.call_count, 3)
                if attempt == 0:
                    shutil.rmtree(root / 'work')
            (root / 'work/raw/elliptic' / FILES[0]).write_text('tampered')
            with self.assertRaisesRegex(ValueError, 'hashes/size/provenance'):
                run_workflow(repo, root / 'work', {'source': 'pyg'}, root / 'store', run_tests=False)
            self.assertEqual(fetch.call_count, 3)
